    'medical_history_management_body': {
      'tr': 'Tıbbi geçmişinizi yönetin. Hastalıklar, ameliyatlar ve aile öyküsü kayıtlarınızı burada saklayın. Doktor kontrolünde paylaşıma hazır.',
